import type { ThumbnailAppearance, ThumbnailsConfig } from '@mintlify/validation';
export type OgAppearance = `${ThumbnailAppearance}`;
export type OgPreset = 'legacy' | NonNullable<ThumbnailsConfig['preset']>;
export type OgSurface = NonNullable<ThumbnailsConfig['surface']>;
export type OgEyebrowStyle = NonNullable<NonNullable<ThumbnailsConfig['eyebrow']>['style']>;
export type OgImageAsset = {
    bytes: Uint8Array;
    contentType: string;
};
export type OgFontFace = {
    data: ArrayBuffer | Buffer;
    weight: 400 | 500 | 600 | 700;
};
export type OgFont = {
    family: string;
    faces: OgFontFace[];
};
export type OgThemeInput = {
    appearance?: string;
    primaryColor?: string;
    lightColor?: string;
    backgroundLight?: string;
    backgroundDark?: string;
    surface?: OgSurface;
    eyebrowColor?: string;
};
export type OgCardInput = {
    preset?: OgPreset;
    eyebrowStyle?: OgEyebrowStyle;
    eyebrow?: string | null;
    title?: string | null;
    description?: string | null;
    theme: OgThemeInput;
    logo?: OgImageAsset | null;
    background?: OgImageAsset | null;
    font?: OgFont | null;
};
